#include "floppy144_drawing_runtime.h"
#include "floppy144_game_data.h"
#include <stddef.h>
#include <string.h>
static uint32_t Floppy144DrawingColour(const char*pszId){uint32_t u;for(u=0;u<Floppy144GameDataRecordCount();++u){const Floppy144DataRecord*p=Floppy144GameDataRecordAt(u);if(p&&p->eKind==FLOPPY144_DATA_COLOUR&&p->pszId&&pszId&&strcmp(p->pszId,pszId)==0)return FLOPPY144_RGB((uint32_t)p->n0,(uint32_t)p->n1,(uint32_t)p->n2);}return FLOPPY144_RGB(202U,211U,205U);}
static int32_t Floppy144DrawingScale(int32_t o,int32_t e,int32_t v){return o+(e*v)/100;}
static void Floppy144DrawingPixel(Floppy144Surface*p,int32_t x,int32_t y,uint32_t c){if(x<0||y<0)return;Floppy144DrawFillRect(p,(uint32_t)x,(uint32_t)y,1U,1U,c);}
static void Floppy144DrawingLine(Floppy144Surface*p,int32_t x0,int32_t y0,int32_t x1,int32_t y1,uint32_t c){int32_t dx=x1>=x0?x1-x0:x0-x1,sx=x0<x1?1:-1,dy=-(y1>=y0?y1-y0:y0-y1),sy=y0<y1?1:-1,err=dx+dy;for(;;){int32_t e2;Floppy144DrawingPixel(p,x0,y0,c);if(x0==x1&&y0==y1)break;e2=2*err;if(e2>=dy){err+=dy;x0+=sx;}if(e2<=dx){err+=dx;y0+=sy;}}}
static void Floppy144DrawingEllipse(Floppy144Surface*p,int32_t x,int32_t y,int32_t w,int32_t h,uint32_t c){int32_t cx=x+w/2,cy=y+h/2,rx=w/2,ry=h/2,step;for(step=0;step<64;++step){int32_t q=step/16,t=step%16,xo,yo;switch(q){case 0:xo=rx-(rx*t*t)/256;yo=(ry*t)/16;break;case 1:xo=-(rx*t)/16;yo=ry-(ry*t*t)/256;break;case 2:xo=-rx+(rx*t*t)/256;yo=-(ry*t)/16;break;default:xo=(rx*t)/16;yo=-ry+(ry*t*t)/256;break;}Floppy144DrawingPixel(p,cx+xo,cy+yo,c);}}
bool Floppy144DrawingRuntimeDraw(Floppy144Surface*pSurface,const char*pszDrawingId,int32_t nX,int32_t nY,int32_t nWidth,int32_t nHeight){uint32_t u;bool bFound=false;if(!pSurface||!pszDrawingId||nWidth<=0||nHeight<=0)return false;for(u=0;u<Floppy144GameDataRecordCount();++u){const Floppy144DataRecord*p=Floppy144GameDataRecordAt(u);uint32_t c;int32_t x,y,w,h;if(!p||p->eKind!=FLOPPY144_DATA_DRAWING_PRIMITIVE||!p->pszId||strcmp(p->pszId,pszDrawingId)!=0)continue;bFound=true;c=Floppy144DrawingColour(p->pszB);x=Floppy144DrawingScale(nX,nWidth,p->n0);y=Floppy144DrawingScale(nY,nHeight,p->n1);w=(nWidth*p->n2)/100;h=(nHeight*p->n3)/100;if(strcmp(p->pszA,"fill_rect")==0){if(x>=0&&y>=0&&w>0&&h>0)Floppy144DrawFillRect(pSurface,(uint32_t)x,(uint32_t)y,(uint32_t)w,(uint32_t)h,c);}else if(strcmp(p->pszA,"stroke_rect")==0){if(x>=0&&y>=0&&w>0&&h>0)Floppy144DrawRect(pSurface,(uint32_t)x,(uint32_t)y,(uint32_t)w,(uint32_t)h,c);}else if(strcmp(p->pszA,"line")==0)Floppy144DrawingLine(pSurface,Floppy144DrawingScale(nX,nWidth,p->n0),Floppy144DrawingScale(nY,nHeight,p->n1),Floppy144DrawingScale(nX,nWidth,p->n2),Floppy144DrawingScale(nY,nHeight,p->n3),c);else if(strcmp(p->pszA,"circle")==0){int32_t r=(nWidth<nHeight?nWidth:nHeight)*p->n2/100;Floppy144DrawingEllipse(pSurface,x-r,y-r,r*2,r*2,c);}else if(strcmp(p->pszA,"ellipse")==0)Floppy144DrawingEllipse(pSurface,x,y,w,h,c);}return bFound;}
